import numpy as np
def comps(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and not seen[i][j]:
                stack=[(i,j)]; seen[i][j]=True; c=[]
                while stack:
                    y,x=stack.pop(); c.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx] and not seen[ny][nx]:
                            seen[ny][nx]=True; stack.append((ny,nx))
                out.append(c)
    return out
