def shift(g,n=-2):
    out=[]; 
    for r in g:
        sh=[0]*n+r
        out.append(sh[:len(g[0])] if len(sh)<=len(g[0]) else None or []) or []
    return [[0]*(len(g[0])-max(0,len(r)-n)) + r[n:] if n<0 else [r[j-n] if j>=n else 0 for j in range(len(g[0]))] for r in g]
